"""Generate summary.csv and the final 474-Val-only offset-grid report."""
import csv,json
from pathlib import Path
ROOT=Path('results/offset_grid_halfstride');VIEWS={'X':'x','Y':'y','XY':'xy'}
def read(p):return json.loads((ROOT/p).read_text())
def rows(p):
    with (ROOT/p).open(encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
def table(h,rs):return '\n'.join(['| '+' | '.join(h)+' |','| '+' | '.join(['---']*len(h))+' |']+['| '+' | '.join(str(x).replace('|','/') for x in r)+' |' for r in rs])
def main():
    context=read('audit/execution_context.json');baseline=read('exact_combo/baseline/metrics.json');geometry=read('audit/geometry_tests.json');candidate=read('audit/candidate_summary.json');proposal=read('audit/proposal_summary.json');po=read('audit/rescue_overlap.json');eo=read('audit/exact_rescue_overlap.json');folds=read('audit/fold_audit.json');attrs=rows('audit/gt_attribution.csv');details=rows('audit/gt_detailed_audit.csv');rt=rows('audit/roundtrip_changes.csv')
    metrics={k:read(f'exact_combo/{v}/metrics.json') for k,v in VIEWS.items()};manifests={k:read(f'{v}/cache/manifest.json') for k,v in VIEWS.items()};summ=[];gates={}
    for vid,view in VIEWS.items():
        m=metrics[vid];g=m['float_group_audit'];r=m['roundtrip_group_audit'];f=next(x for x in folds if x['config']==vid and x['fold']=='summary');c=candidate['views'][vid]
        rep_only=any(x['config']==vid and x['float_status']!=x['roundtrip_status'] for x in rt)
        checks={'float_net_ge_4':g['net_gain']>=4,'roundtrip_net_ge_4':r['net_gain']>=4,'four_images':g['rescue_images']>=4,'four_groups':g['rescue_groups']>=4,'two_classes':g['rescue_classes']>=2,'two_failure_clusters':g['rescue_failure_types']>=2,'regression_le_1':g['regressed']<=1,'net_without_largest_ge_2':g['net_gain_without_largest_group']>=2,'two_positive_folds':int(f['positive_folds'])>=2,'no_negative_fold':int(f['negative_folds'])==0,'not_all_representation_only':g['rescued']>0 and not (g['net_gain']==0 and rep_only),'cache_geometry_provenance_pass':geometry['status']=='PASS' and candidate['status']=='PASS'};gates[vid]=checks
        summ.append({'config':vid,'offset_x':manifests[vid]['offset_x'],'offset_y':manifests[vid]['offset_y'],'images':474,'tile_rows':c['tile_rows'],'tile_count_ratio_to_o':c['tile_count_ratio_to_o'],'candidate_rows':c['candidate_rows'],'candidate_per_image':c['candidate_per_image'],'candidate_per_tile':c['candidate_per_tile'],'runtime_seconds':manifests[vid]['runtime_seconds'],'peak_gpu_allocated_mb':manifests[vid]['peak_gpu_mem_mb'],'peak_gpu_reserved_mb':manifests[vid]['peak_gpu_reserved_mb'],'origin_jaccard_to_o':c['origin_jaccard']['mean'],'new_origin_fraction':c['new_origin_fraction']['mean'],**proposal[vid],'float_tp':m['float_tp'],'float_fn':m['float_fn'],'float_recall':m['float_tp']/845,'roundtrip_tp':m['roundtrip_tp'],'roundtrip_fn':m['roundtrip_fn'],'roundtrip_recall':m['roundtrip_tp']/845,**{k:g[k] for k in ['rescued','regressed','net_gain','rescue_images','rescue_groups','rescue_classes','rescue_failure_types','largest_group_contribution','net_gain_without_largest_group']},'positive_folds':f['positive_folds'],'negative_folds':f['negative_folds'],'fold_nets':json.dumps(f['fold_nets']),**{k:m[k] for k in ['new_stitched','new_view_participating_stitched','mixed_source_stitched','stitch_only_rescues']},'go':'GO' if all(checks.values()) else 'NO-GO'})
    with (ROOT/'summary.csv').open('w',encoding='utf-8-sig',newline='') as f:w=csv.DictWriter(f,fieldnames=list(summ[0]));w.writeheader();w.writerows(summ)
    eligible=[r['config'] for r in summ if r['go']=='GO'];nets={k:metrics[k]['float_group_audit']['net_gain'] for k in VIEWS}
    if not eligible:mechanism='NO_USEFUL_OFFSET_GRID'
    elif nets['XY']>max(nets['X'],nets['Y']):mechanism='XY_CONTEXT_DOMINANT'
    elif nets['X']>nets['Y'] and eo['counts']['X-only']>0:mechanism='X_BOUNDARY_DOMINANT'
    elif nets['Y']>nets['X'] and eo['counts']['Y-only']>0:mechanism='Y_BOUNDARY_DOMINANT'
    else:mechanism='MIXED_AXIS_GEOMETRY'
    rec=sorted(eligible,key=lambda k:(-nets[k],metrics[k]['float_group_audit']['regressed'],-metrics[k]['float_group_audit']['rescue_groups'],candidate['views'][k]['candidate_rows']))[0] if eligible else 'NONE'
    decision={'decision':'GO' if eligible else 'NO-GO','recommended_view_for_future_test':rec,'mechanism':mechanism,'gates':gates,'test_hidden_run':'NO','competition_submission':'NO'};(ROOT/'decision.json').write_text(json.dumps(decision,indent=2))
    geomrows=[]
    for vid in VIEWS:
        rescued=[r for r in details if vid in r['exact_rescued'].split(',')]
        dv=[float(r[f'{vid}_max_visible'])-float(r['O_max_visible']) for r in rescued];geomrows.append((vid,len(rescued),sum(dv)/len(dv) if dv else 0,'see audit/gt_geometry_exposure.csv'))
    lines=['# RareOS Half-Stride Offset Grid — 474-Val-only report','','## A. Execution status','',f'- Repo HEAD: `{context["repo_head"]}`',f'- Workspace dirty: {bool(context["workspace_dirty"])}',f'- Python: `{context["python"].splitlines()[0]}`; PyTorch `{context["torch"]}`; Torchvision `{context["torchvision"]}`; Ultralytics `{context["ultralytics"]}`',f'- GPU: {context["gpu"]}',f'- Weights: `{context["weights"]}`; SHA256 `{context["weights_sha256"]}`','- Test/Hidden run = **NO**; Test/Hidden GT accessed = **NO**; competition submission = **NO**.','','## B. Formal BASE reproduction','',f'Expected and actual: float **{baseline["float_tp"]}/{baseline["float_fn"]}**, roundtrip **{baseline["roundtrip_tp"]}/{baseline["roundtrip_fn"]}**; final detections **{baseline["final_detection_count"]:,}**, stitched **{baseline["stitched_count"]:,}**: **PASS**.','','## C. Grid definitions','','Original uses Script14 `get_starts()`. OFFSET=384=`stride//2`; offset starts preserve edge anchors `{0,last}` and add internal `384+k*768`. X offsets x only, Y offsets y only, XY offsets both; pixels remain unflipped.','','## D. Geometry tests','',table(['check','status'],geometry['checks'].items()),'','## E. Tile-origin novelty','',table(['view','tiles/image mean','ratio to O','origin Jaccard mean','new-origin fraction mean'],[(k,f'{candidate["views"][k]["tiles_per_image"]["mean"]:.3f}',f'{candidate["views"][k]["tile_count_ratio_to_o"]:.3f}',f'{candidate["views"][k]["origin_jaccard"]["mean"]:.4f}',f'{candidate["views"][k]["new_origin_fraction"]["mean"]:.4f}') for k in VIEWS]),'','## F. Cache summary','',table(['view','images','candidates','cand/tile','coord residual','runtime s','GPU alloc/reserved MiB'],[(k,474,f'{candidate["views"][k]["candidate_rows"]:,}',f'{candidate["views"][k]["candidate_per_tile"]:.2f}',read(f'audit/cache_{VIEWS[k]}.json')['coord_residual'],f'{manifests[k]["runtime_seconds"]:.1f}',f'{manifests[k]["peak_gpu_mem_mb"]:.1f}/{manifests[k]["peak_gpu_reserved_mb"]:.1f}') for k in VIEWS]),'','Candidate/tile ratios to O are '+', '.join(f'{k}={candidate["views"][k]["candidate_per_tile_ratio_to_o"]:.3f}' for k in VIEWS)+'; no order-of-magnitude anomaly.','','## G. Proposal rescue','',table(['view','IoU≥.30','IoU≥.40','direct','images','groups','classes'],[(k,proposal[k]['iou_ge_030'],proposal[k]['iou_ge_040'],proposal[k]['direct_rescue'],proposal[k]['direct_rescue_images'],proposal[k]['direct_rescue_groups'],proposal[k]['direct_rescue_classes']) for k in VIEWS]),'','## H. Exact Combo','',table(['config','float TP/FN','roundtrip TP/FN','rescued','regressed','net','images','groups','classes'],[(k,f'{metrics[k]["float_tp"]}/{metrics[k]["float_fn"]}',f'{metrics[k]["roundtrip_tp"]}/{metrics[k]["roundtrip_fn"]}',*[metrics[k]['float_group_audit'][x] for x in ['rescued','regressed','net_gain','rescue_images','rescue_groups','rescue_classes']]) for k in VIEWS]),'','Only BASE+X, BASE+Y, BASE+XY were run. Frozen source order is BASE active O+Baseline, selected HFlip, then the complete new view. Script42 NMS/stitch/submission_row and Script14 matcher are reused unchanged.','','## I. Rescue overlap','',table(['set','proposal','exact'],[(k,po['counts'][k],eo['counts'][k]) for k in po['counts']]),'',table(['pair','proposal Jaccard','exact Jaccard'],[(k,po['jaccard'][k],eo['jaccard'][k]) for k in po['jaccard']]),'','## J. Geometry mechanism','',table(['view','exact rescues','mean Δ max-visible among rescued','details'],geomrows),'','Per-GT visible fraction, vertical/horizontal boundary distances, intersection counts, aspect and area are in `audit/gt_geometry_exposure.csv` and `audit/gt_detailed_audit.csv`. This is post-hoc mechanism analysis only.','','## K. Stitch provenance','',table(['view','new stitched','new-view participation','mixed-source','stitch-only rescues'],[(k,*[metrics[k][x] for x in ['new_stitched','new_view_participating_stitched','mixed_source_stitched','stitch_only_rescues']]) for k in VIEWS]),'','Every post-NMS source row and stitched-member box is independently checked.','','## L. Group robustness','',table(['view','largest group','contribution','rescued after removal','regressed after removal','net after removal'],[(k,*[metrics[k]['float_group_audit'][x] for x in ['largest_group','largest_group_contribution','rescued_without_largest_group','regressed_without_largest_group','net_gain_without_largest_group']]) for k in VIEWS]),'','## M. Deterministic fold robustness','',table(['config','fold nets','positive','negative'],[(r['config'],r['fold_nets'],r['positive_folds'],r['negative_folds']) for r in folds if r['fold']=='summary']),'','Fold is `int(sha256(group_id)[:8],16)%3`; this is dispersion, not independent validation.','','## N. Mechanism conclusion','',f'**{mechanism}**.','','## O. Strong GO / NO-GO','',f'**{decision["decision"]}**; recommended_view_for_future_test = **{rec}**.',table(['view','decision','failed criteria'],[(k,'GO' if all(gates[k].values()) else 'NO-GO',', '.join(x for x,y in gates[k].items() if not y) or 'none') for k in VIEWS]),'','Roundtrip-only status changes: '+(str(len(rt)) if rt else '0')+'. Regressions are listed in `audit/gt_attribution.csv`.','','## Per-GT audit','','The required current 14 BASE FN plus every regression are recorded with bbox, aspect, area, O/X/Y/XY proposal IoU, visibility, boundary distances, tile intersections, and exact status in `audit/gt_detailed_audit.csv`.','','## Independent verification','',('Independent persisted-artifact verification: **PASS**.' if (ROOT/'audit/independent_verification.json').exists() else 'Draft generated after independent pre-verification; final verification pending.'),'','Execution stopped here. Test/Hidden run = **NO**; competition submission = **NO**.']
    (ROOT/'report.md').write_text('\n'.join(lines),encoding='utf-8');print(json.dumps(decision,indent=2))
if __name__=='__main__':main()
